class MobDocMovementJournal extends TFMDocumentHandler
{
    public inventJournalTrans           inventJournalTrans;
    public inventJournalTable           inventJournalTable;
    public inventDim                    inventDim;
    public inventTable                  inventTable;
    public TFMInventDimSetup            mobInventDimSetup;
