public Map addTranslations()
{
    Map ret = super();
    ret.insert('CreateMovementJournalLine',"@SYS319116");
    ret.insert('CreateMovementJournal', "@SYS18287");
    return ret;
}

[TFMReferenceDataMethod]
public TFMReferenceDataConfiguration CreateMovementJournalHeader()
{
    TFMReferenceDataConfiguration conf = new TFMReferenceDataConfiguration();
    TFMRegistrationCollectorText	journalDesc = new TFMRegistrationCollectorText(1,extendedTypeStr(Description),"@SYS6303","@SYS6303","@SYS6303");
    TFMRegistrationCollectorList	journalList = new TFMRegistrationCollectorList(2,extendedTypeStr(JournalNameId),"@MobileWMS:JournalName","@MobileWMS:JournalName","@MobileWMS:JournalName");


        journalList.parmDataTable(methodStr(MobDocMovementJournal,JournalNames));
        conf.addCollector(journalList);

        journalDesc.parmOptional(false);
        conf.addCollector(journalDesc);

    return conf;
}

[TFMReferenceDataMethod]
public TFMReferenceDataFilterList JournalNames()
{
    TFMReferenceDataFilterList	list = new TFMReferenceDataFilterList();
    InventJournalName           jn;
    MapEnumerator				mEnum = MobInventAdjustmentCauses::getAllCauses().getEnumerator();

    while select jn where jn.JournalType == InventJournalType::Movement
    {
        list.addValue(jn.JournalNameId,jn.Description);
    }

    return list;
}

/// <summary>
/// Method to create the filter/header for the create Profit/Loss page.
/// </summary>
/// <returns>The Filter as an XML formatted string.</returns>
[TFMReferenceDataMethod]
public TFMReferenceDataConfiguration CreateMovementJournalLineHeader()
{
    TFMReferenceDataConfiguration refConf = this.MovementJournalCfgHeader();
    // Warehouse
    refConf.addCollector(TFMGetReferenceData::createDefaultWarehouseReferenceData(1,MobConstants::Warehouse(), "@SYS6437",methodStr(TFMGetReferenceData,WarehouseList)));
    // Item number text box
    refConf.addCollector(TFMGetReferenceData::defaultItemIdCollector(3));

    return refConf;
}

