/// <summary>
/// Method to return Profit/Loss Journal Line elements to the mobile client.
/// </summary>
/// <returns>A MobLookupResponseElement instance containing the data needed for he lookup page on the mobile device.</returns>
protected TFMLookupResponseElement lookupMovementJournalLines()
{
    return MobInventJournalTableCommon::lookupInventJournalLines(docRequest.parmJournalId(),this);
}

/// <summary>
/// Method to return Profit/Loss Journal elements to the mobile client.
/// </summary>
/// <returns>A MobLookupResponseElement instance containing the data needed for he lookup page on the mobile device.</returns>

protected TFMLookupResponseElement lookupMovementJournals()
{
    return MobInventJournalTableCommon::lookupInventJournals(InventJournalType::Movement, docRequest.parmJournalId(), docRequest.parmInventLocationId() ? docRequest.parmInventLocationId() : docRequest.parmWarehouse());
}

public boolean preProcess()
{

    // Get the dimension setup for the item
    docRequest = request;

    mobInventDimSetup   = TFMInventDimSetup::Construct(docRequest.parmInventTable());
    return true;
}

/// <summary>
/// Method to create Profit/Loss Journal line configurations.
/// </summary>

public Map createCreatePLJournalLineConfiguration()
{
    Map returnMap;
    SysDictType dictType;
    int add = 10;
    InventDimParm parm =  InventDimParm::activeDimFlag(InventDimGroupSetup::newInventTable(docRequest.parmInventTable()));
    parm.InventSiteIdFlag = NoYes::No;
    parm.InventLocationIdFlag = NoYes::No;

    #if.isAX6
    parm.WMSPalletIdFlag = mobInventDimSetup.registerWMSPallet();
    parm.WMSLocationIdFlag = !mobInventDimSetup.registerWMSPallet();
    #endif

    returnMap = MobInventDimHelper::GetInventDimCollectors(add, mobInventDimSetup, parm);

    if (!returnMap.exists(fieldStr(InventDim, inventSerialId)))
    {
        // If serial numbers are not used we ask for a quantity (for serial numbers the quantity is always 1)
        add+=100;
        dictType = new SysDictType(extendedTypeNum(Qty));
        returnMap.insert(MobConstants::Quantity(),TFMRegistrationCollectorDecimal::DecimalStepMap(add,MobConstants::Quantity(),"@SYS130676",dictType.label(),'',true,'',-20000,10000000,14));
    }

    return returnMap;
}

/// <summary>
/// Method to create Profit/Loss journals.
/// </summary>
[TFMPostMethod(tableStr(inventJournalTable))]
public void postCreateMovementJournal()
{
    InventJournalTableData		jourTableData;
    InventJournalName			inventJournalName;
    str							description			= docRequest.getFieldValue(extendedTypeStr(description));
    InventLocationId            inventLocationId    = docRequest.parmContextValues().getFieldValue(extendedTypeStr(InventLocationId));

    // Get the name of the profit/loss journal to create
    inventJournalName = InventJournalName::find(docRequest.getFieldValue(extendedTypeStr(JournalNameId)),true);

    ttsBegin;

    jourTableData = JournalTableData::newTable(inventJournalTable);

    inventJournalTable.JournalId            = jourTableData.nextJournalId();
    inventJournalTable.JournalType          = inventJournalType::Movement;

    inventJournalTable.InventLocationId		= inventLocationId;
    inventJournalTable.InventSiteId			= InventLocation::find(inventLocationId).InventSiteId;

    inventJournalTable.MobReleasedToMobile = true;
    inventJournalTable.NumOfLines           = 0;
    jourTableData.initFromJournalName(inventJournalName);
    inventJournalTable.Description          = description;

    inventJournalTable.insert();
    ttsCommit;

    resultStr = "@MobileWMS:MovementJournalcreatedsuccesfull";
}

/// <summary>
/// Method to create Profit/Loss journal lines.
/// </summary>
[TFMPostMethod(tableStr(inventJournalTable)),TFMPostMethod(tableStr(inventJournalTrans))]
public void postCreateMovementJournalLine()
{
    InventJournalId         inventJournalId;

    inventJournalId     = docRequest.parmJournalId();

    // Find the journal to add a line to
    inventJournalTable = InventJournalTable::find(inventJournalId,true);

    // Initialize the new journal line
    inventJournalTrans.clear();
    inventJournalTrans.initFromInventJournalTable(inventJournalTable);
    inventJournalTrans.selectForUpdate(true);
    inventJournalTrans.initValue();
    inventJournalTrans.initFromInventJournalTable( inventJournalTable );

    inventJournalTrans.initFromInventTable(docRequest.parmInventTable());

    // If a serial number was entered the quantity is always -1

    inventJournalTrans.Qty = docRequest.parmQuantity();
    inventJournalTrans.setInventDimId(docRequest.createInventDim(inventDim).inventDimId);

    // Set the cost price for the line
    inventJournalTrans.setCostPrice(inventJournalTrans.InventDimId, inventJournalTrans.inventDim(), inventJournalTrans.inventTableModuleInvent());

    inventJournalTrans.Worker = HcmWorker::userId2Worker(curUserId());
    inventJournalTrans.insert(false);

    // Calculate the number of lines
    inventJournalTable::initTotal(inventJournalTable);
    inventJournalTable.update();

    resultStr = "@SYS80122";
}

public void postUpdateMovementJournalLine()
{
    InventJournalId         inventJournalId;

    inventJournalId     = docRequest.parmJournalId();
    inventJournalTrans  = docRequest.getReferredRecord();
    ttsbegin;
    inventJournalTable = InventJournalTable::find(inventJournalId,true);
    inventJournalTrans.selectForUpdate(true);
    inventJournalTrans.Qty = docRequest.parmQuantity();        
    inventJournalTrans.update(false);

    // Calculate the number of lines
    inventJournalTable::initTotal(inventJournalTable);
    inventJournalTable.update();
    ttscommit;
    resultStr = "@SYS80122";
}
